+package com.example.itemtracker;
+
+import com.example.itemtracker.views.MainView;
+import com.vaadin.browserless.BrowserlessUIContext;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.html.ListItem;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.textfield.TextField;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.context.annotation.Import;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+
+@SpringBootTest
+@Import(TestConfig.class)
+public class ItemTrackerViewTest {
+
+    @Autowired
+    private BrowserlessUIContext uiContext;
+
+    @BeforeEach
+    void open() {
+        uiContext.navigate(MainView.class);
+        // The UI context is shared between tests, so start each one from an empty list
+        uiContext.findInView(Button.class).withText("Clear").single().click();
+    }
+
+    @Test
+    void addAppendsItemClearsFieldAndUpdatesCount() {
+        typeAndAdd("Milk");
+        typeAndAdd("Milk");
+
+        assertEquals(2, uiContext.findInView(ListItem.class).all().size());
+        assertEquals("Milk", uiContext.findInView(ListItem.class).all().get(1).getText());
+        assertEquals("", textField().getValue());
+        assertEquals("Items: 2", countSpan().getText());
+    }
+
+    @Test
+    void blankAddIsRejected() {
+        typeAndAdd("   ");
+
+        assertEquals(0, uiContext.findInView(ListItem.class).all().size());
+        assertEquals("Items: 0", countSpan().getText());
+        assertTrue(textField().isInvalid());
+    }
+
+    @Test
+    void clearRemovesAllItems() {
+        typeAndAdd("Eggs");
+        uiContext.findInView(Button.class).withText("Clear").single().click();
+
+        assertEquals(0, uiContext.findInView(ListItem.class).all().size());
+        assertEquals("Items: 0", countSpan().getText());
+
+        typeAndAdd("Bread");
+        assertEquals(1, uiContext.findInView(ListItem.class).all().size());
+        assertFalse(textField().isInvalid());
+    }
+
+    private void typeAndAdd(String value) {
+        textField().setValue(value);
+        uiContext.findInView(Button.class).withText("Add").single().click();
+    }
+
+    private TextField textField() {
+        return uiContext.findInView(TextField.class).single();
+    }
+
+    private Span countSpan() {
